node - <<'NODE'
const fs = require('fs');
const path = require('path');
const {spawnSync} = require('child_process');
const source = fs.readFileSync('index.html', 'utf8');
const axe = fs.readFileSync('/tmp/axe.min.js', 'utf8');
const testHtml = source.replace('</body>', `<script>${axe}</script><script>\n(async () => {\n  const results = await axe.run(document, { resultTypes: ['violations'] });\n  const wcag = results.violations.filter((v) => !v.tags.includes('best-practice'));\n  const bp = results.violations.filter((v) => v.tags.includes('best-practice'));\n  document.body.innerHTML = '<pre id="axe-results">' + JSON.stringify({\n    wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),\n    bp: bp.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))\n  }) + '</pre>';\n})();\n</script></body>`);
const tempPath = path.join('/tmp', `axe-${process.pid}.html`);
fs.writeFileSync(tempPath, testHtml);
const result = spawnSync('chromium', ['--headless', '--no-sandbox', '--disable-gpu', '--run-all-compositor-stages-before-draw', '--virtual-time-budget=5000', '--dump-dom', `file://${tempPath}`], {encoding: 'utf8'});
fs.unlinkSync(tempPath);
if (result.status !== 0) {
  process.stderr.write(result.stderr || result.stdout);
  process.exit(result.status || 1);
}
const match = result.stdout.match(/<pre id="axe-results">([^<]+)<\/pre>/);
if (!match) {
  process.stderr.write('axe results not found\n');
  process.exit(1);
}
const report = JSON.parse(match[1].replace(/&quot;/g, '"').replace(/&amp;/g, '&'));
console.log(JSON.stringify(report, null, 2));
if (report.wcag.length) process.exit(1);
