         <h1 id="quiz-title">Computer Languages Quiz</h1>
         <p class="intro">Choose every answer that applies. Some questions may have more than one correct choice.</p>
       </div>

       <form id="quiz-form" novalidate>
         <div class="form-field">
           <fieldset aria-describedby="q1-help">
             <legend>1. Which of these are programming languages?</legend>
             <p class="help-text" id="q1-help">Help: Select all options that are used to write executable programs or scripts.</p>
             <div class="choices">
               <div class="choice">
                 <input type="checkbox" id="q1-python" name="q1" value="Python" data-correct="true">
                 <label for="q1-python">Python</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q1-html" name="q1" value="HTML">
                 <label for="q1-html">HTML</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q1-ruby" name="q1" value="Ruby" data-correct="true">
                 <label for="q1-ruby">Ruby</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q1-css" name="q1" value="CSS">
                 <label for="q1-css">CSS</label>
               </div>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>2. Which languages are commonly used for web front-end behavior or apps?</legend>
             <div class="choices">
               <div class="choice">
                 <input type="checkbox" id="q2-javascript" name="q2" value="JavaScript" data-correct="true">
                 <label for="q2-javascript">JavaScript</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q2-typescript" name="q2" value="TypeScript" data-correct="true">
                 <label for="q2-typescript">TypeScript</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q2-sql" name="q2" value="SQL">
                 <label for="q2-sql">SQL</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q2-swift" name="q2" value="Swift">
                 <label for="q2-swift">Swift</label>
               </div>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>3. Which languages are often described as low-level or systems languages?</legend>
             <div class="choices">
               <div class="choice">
                 <input type="checkbox" id="q3-c" name="q3" value="C" data-correct="true">
                 <label for="q3-c">C</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q3-rust" name="q3" value="Rust" data-correct="true">
                 <label for="q3-rust">Rust</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q3-scratch" name="q3" value="Scratch">
                 <label for="q3-scratch">Scratch</label>
               </div>
               <div class="choice">
                 <input type="checkbox" id="q3-assembly" name="q3" value="Assembly" data-correct="true">
                 <label for="q3-assembly">Assembly</label>
               </div>
             </div>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Check answers</button>
           <p class="result" id="quiz-result" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#quiz-form");
     const result = document.querySelector("#quiz-result");
     const questions = ["q1", "q2", "q3"];

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const score = questions.reduce((total, questionName) => {
         const answers = [...form.querySelectorAll(`input[name="${questionName}"]`)];
         const isCorrect = answers.every((answer) => answer.checked === answer.hasAttribute("data-correct"));
         return isCorrect ? total + 1 : total;
       }, 0);

       result.textContent = `You scored ${score} out of ${questions.length}.`;
       result.classList.toggle("error", score < questions.length);
     });
   </script>
